import 'dart:async';import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:locallink/core/bloc/bloc_utils.dart';import 'package:locallink/core/models/attachment.dart';import 'package:locallink/core/models/group.dart';import 'package:locallink/features/groups/domain/group_messaging_repository_contract.dart';
final class GroupChatState extends Equatable{final LocalGroup group;final String localDeviceId;final List<GroupMessage> messages;final bool isLoading,isSending;final Object? error;const GroupChatState({required this.group,required this.localDeviceId,this.messages=const [],this.isLoading=false,this.isSending=false,this.error});GroupChatState copyWith({List<GroupMessage>? messages,bool? isLoading,bool? isSending,Object? error,bool clearError=false})=>GroupChatState(group:group,localDeviceId:localDeviceId,messages:messages??this.messages,isLoading:isLoading??this.isLoading,isSending:isSending??this.isSending,error:clearError?null:(error??this.error));@override List<Object?>get props=>[group,localDeviceId,messages,isLoading,isSending,error.toString()];}
final class GroupChatBloc extends Cubit<GroupChatState>{final GroupMessagingRepositoryContract repository;late final StreamSubscription<GroupMessage> _incoming;GroupChatBloc({required this.repository,required LocalGroup group,required String localDeviceId}):super(GroupChatState(group:group,localDeviceId:localDeviceId)){_incoming=repository.incoming.listen(_onIncoming);}List<GroupMessage> get messages=>state.messages;bool get isLoading=>state.isLoading;bool get isSending=>state.isSending;Object? get error=>state.error;bool isMine(GroupMessage m)=>m.senderId==state.localDeviceId;Future<void> load()async{emit(state.copyWith(isLoading:true,clearError:true));try{emit(state.copyWith(messages:await repository.history(state.group.id),isLoading:false));}catch(e){emit(state.copyWith(error:e,isLoading:false));}}Future<GroupMessage> send(String body,{List<PickedFile> attachments=const []})async{if(state.isSending)throw StateError('A message is already being sent');if(body.trim().isEmpty&&attachments.isEmpty)throw const FormatException('Message or attachment required');emit(state.copyWith(isSending:true,clearError:true));try{final m=await repository.send(state.group.id,body.trim(),attachments:attachments);_upsert(m);return m;}catch(e){emit(state.copyWith(error:e));rethrow;}finally{emit(state.copyWith(isSending:false));}}void _onIncoming(GroupMessage m){if(m.groupId!=state.group.id)return;_upsert(m);}void _upsert(GroupMessage m){final next=[...state.messages];final i=next.indexWhere((x)=>x.id==m.id);if(i<0)next.add(m);else next[i]=m;emit(state.copyWith(messages:next));}@override Future<void> close()async{await _incoming.cancel();return super.close();}}
